using System;using System.Collections.Generic;using System.IO;using UnityEngine;using AshenCrown.Progression;using AshenCrown.Localization;using AshenCrown.Core;
namespace AshenCrown.Save{[Serializable]public class AshenSaveData{public int version=1;public string language="English";public float masterVolume=1f;public bool reducedMotion;public bool subtitles=true;public int skillPoints;public List<string> unlockedSkills=new List<string>();public List<InventoryItem> inventory=new List<InventoryItem>();}
public sealed class SaveLoadSystem:MonoBehaviour{public static SaveLoadSystem Instance{get;private set;}public string SavePath=>Path.Combine(Application.persistentDataPath,"ashen_crown_save.json");void Awake(){if(Instance!=null&&Instance!=this){Destroy(gameObject);return;}Instance=this;DontDestroyOnLoad(gameObject);}
public bool Save(){var d=new AshenSaveData();if(LocalizationService.Instance!=null)d.language=LocalizationService.Instance.CurrentLanguage.ToString();if(GameSettingsService.Instance!=null){d.masterVolume=GameSettingsService.Instance.MasterVolume;d.reducedMotion=GameSettingsService.Instance.ReducedMotion;d.subtitles=GameSettingsService.Instance.Subtitles;}if(SkillTreeSystem.Instance!=null){d.skillPoints=SkillTreeSystem.Instance.SkillPoints;d.unlockedSkills=SkillTreeSystem.Instance.CaptureUnlocked();}if(InventorySystem.Instance!=null)d.inventory=InventorySystem.Instance.Capture();try{File.WriteAllText(SavePath,JsonUtility.ToJson(d,true));return true;}catch(Exception e){Debug.LogError("[SaveLoadSystem] Save failed: "+e.Message);return false;}}
public bool Load(){if(!File.Exists(SavePath))return false;try{var d=JsonUtility.FromJson<AshenSaveData>(File.ReadAllText(SavePath));if(d==null)return false;if(LocalizationService.Instance!=null)LocalizationService.Instance.SetLanguage(d.language);if(GameSettingsService.Instance!=null){GameSettingsService.Instance.SetMasterVolume(d.masterVolume);GameSettingsService.Instance.SetReducedMotion(d.reducedMotion);GameSettingsService.Instance.SetSubtitles(d.subtitles);}if(SkillTreeSystem.Instance!=null)SkillTreeSystem.Instance.Restore(d.unlockedSkills,d.skillPoints);if(InventorySystem.Instance!=null)InventorySystem.Instance.Restore(d.inventory);return true;}catch(Exception e){Debug.LogError("[SaveLoadSystem] Load failed: "+e.Message);return false;}}
public bool HasSave()=>File.Exists(SavePath);public void DeleteSave(){if(File.Exists(SavePath))File.Delete(SavePath);}}}